```python
"""Payment projection from PSP webhooks (single payment, integer minor units).

The state holds only the distinct business facts, keyed by business id:
captures, succeeded refunds, failed refunds, the opened dispute and the
latest decision per dispute. The position is a pure function of those facts,
so it cannot depend on arrival order or repeats.

Each delivery posts the difference between the position before and after it.
That keeps the journal append-only, makes each delivery's lines sum to zero
via psp_clearing, and makes the journal sums equal balances() after every event.

The state contains only dicts, lists, strings and ints, so it round-trips
exactly through json.
"""

import re
from datetime import datetime, timedelta

ACCOUNTS = ("available", "reserved", "chargeback_loss", "dispute_fee", "unapplied_refund")
DISPUTE_FEE = 1500

_FRAC_DIGITS = 18
_TS_RE = re.compile(
    r"^\s*(\d{4})-(\d{2})-(\d{2})[Tt ](\d{2}):(\d{2})(?::(\d{2})(?:[.,](\d+))?)?"
    r"\s*(?:([Zz])|([+-])(\d{2})(?::?(\d{2}))?)\s*$"
)
_EPOCH = datetime(1970, 1, 1)


def _instant(text):
    """Parse ISO-8601 with UTC offset into an exact, sortable integer (UTC instant)."""
    m = _TS_RE.match(text)
    if not m:
        raise ValueError("invalid decided_at: %r" % (text,))
    y, mo, d, h, mi, s, frac, z, sign, oh, om = m.groups()
    naive = datetime(int(y), int(mo), int(d), int(h), int(mi), int(s or 0))
    if not z:
        off = timedelta(hours=int(oh), minutes=int(om or 0))
        if sign == "+":
            naive -= off
        else:
            naive += off
    delta = naive - _EPOCH
    seconds = delta.days * 86400 + delta.seconds
    frac_part = int(((frac or "") + "0" * _FRAC_DIGITS)[:_FRAC_DIGITS])
    return seconds * 10 ** _FRAC_DIGITS + frac_part


def _is_amount(v):
    return isinstance(v, int) and not isinstance(v, bool) and v >= 0


def _ensure(state):
    state.setdefault("captures", {})      # capture_id -> amount
    state.setdefault("refunds", {})       # refund_id -> amount (reported succeeded)
    state.setdefault("failed_refunds", {})  # refund_id -> True
    state.setdefault("dispute", None)     # {"id": str, "amount": int}
    state.setdefault("decisions", {})     # dispute_id -> {"at": int, "outcome": str}
    state.setdefault("journal", [])


def _position(state):
    captures = state.get("captures", {})
    refunds = state.get("refunds", {})
    failed = state.get("failed_refunds", {})
    dispute = state.get("dispute")
    decisions = state.get("decisions", {})

    captured = sum(captures.values())
    refunded = sum(a for rid, a in refunds.items() if rid not in failed)
    applied = min(refunded, captured)
    unapplied = refunded - applied
    remaining = captured - applied

    reserved = loss = fee = 0
    if dispute is not None:
        disputed = min(dispute["amount"], remaining)
        dec = decisions.get(dispute["id"])
        outcome = dec["outcome"] if dec else None
        if outcome == "won":
            pass
        elif outcome == "lost":
            loss = disputed
            fee = DISPUTE_FEE
        else:
            reserved = disputed
            fee = DISPUTE_FEE
    available = remaining - reserved - loss
    return {
        "available": available,
        "reserved": reserved,
        "chargeback_loss": loss,
        "dispute_fee": fee,
        "unapplied_refund": unapplied,
    }


def _mutate(state, event):
    etype = event.get("type")
    if etype == "capture.succeeded":
        cid, amt = event.get("capture_id"), event.get("amount_minor")
        if cid is not None and _is_amount(amt):
            state["captures"].setdefault(cid, amt)
    elif etype == "refund.succeeded":
        rid, amt = event.get("refund_id"), event.get("amount_minor")
        if rid is not None and _is_amount(amt):
            state["refunds"].setdefault(rid, amt)
    elif etype == "refund.failed":
        rid = event.get("refund_id")
        if rid is not None:
            state["failed_refunds"][rid] = True
    elif etype == "dispute.opened":
        did, amt = event.get("dispute_id"), event.get("amount_minor")
        if did is not None and _is_amount(amt) and state["dispute"] is None:
            state["dispute"] = {"id": did, "amount": amt}
    elif etype == "dispute.decided":
        did, outcome = event.get("dispute_id"), event.get("outcome")
        if did is None or outcome not in ("won", "lost"):
            return
        try:
            at = _instant(event.get("decided_at"))
        except (ValueError, TypeError):
            return
        cur = state["decisions"].get(did)
        # Latest instant wins; deterministic tie-break on outcome for equal instants.
        if cur is None or (at, outcome) > (cur["at"], cur["outcome"]):
            state["decisions"][did] = {"at": at, "outcome": outcome}


def apply_event(state: dict, event: dict) -> None:
    _ensure(state)
    before = _position(state)
    _mutate(state, event)
    after = _position(state)

    deltas = [(acct, after[acct] - before[acct]) for acct in ACCOUNTS]
    deltas = [(a, d) for a, d in deltas if d != 0]
    if not deltas:
        return
    event_id = event.get("event_id")
    lines = list(deltas)
    contra = -sum(d for _, d in deltas)
    if contra != 0:
        lines.append(("psp_clearing", contra))
    journal_list = state["journal"]
    for acct, amount in lines:
        journal_list.append({
            "line_id": "L%d" % (len(journal_list) + 1),
            "event_id": event_id,
            "account": acct,
            "amount_minor": amount,
        })


def balances(state: dict) -> dict:
    return _position(state)


def journal(state: dict) -> list:
    return [dict(line) for line in state.get("journal", [])]
```
